import json

import pytest

from tapedeck.engine import tape


def _minimal_valid_tape():
    return {
        "session": {
            "sdk": "pytest-sdk",
            "captured_at": "2026-01-02T03:04:05Z",
            "duration_s": 1.25,
        },
        "timeline": [],
        "mocked_modules": {},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }


def test_required_keys_are_the_documented_top_level_keys():
    assert tape.REQUIRED_KEYS == (
        "session",
        "timeline",
        "mocked_modules",
        "metadata",
    )


@pytest.mark.parametrize("missing_key", tape.REQUIRED_KEYS)
def test_validate_tape_rejects_each_missing_required_key(missing_key):
    payload = _minimal_valid_tape()
    del payload[missing_key]

    with pytest.raises(ValueError):
        tape.validate_tape(payload)


def test_validate_tape_accepts_minimal_tape_without_optional_sections():
    tape.validate_tape(_minimal_valid_tape())


def test_validate_tape_does_not_require_value_index_when_it_is_not_required():
    tape.validate_tape(_minimal_valid_tape())


def test_validate_tape_rejects_timeline_event_with_unknown_direction():
    payload = _minimal_valid_tape()
    payload["timeline"] = [{"seq": 0, "t": 0.0, "dir": "sideways"}]

    with pytest.raises(ValueError):
        tape.validate_tape(payload)


def test_validate_tape_accepts_in_and_out_timeline_directions():
    payload = _minimal_valid_tape()
    payload["timeline"] = [
        {"seq": 0, "t": 0.0, "dir": "in"},
        {"seq": 1, "t": 0.1, "dir": "out"},
    ]

    tape.validate_tape(payload)


def test_infer_hierarchical_bindings_maps_every_capitalized_result_prefix():
    paths = [
        "service.Client",
        "service.Client_result.calls",
        "service.Client_result.children.Helper_result.execute",
        "service.lowercase_result.method",
        "service.Client_result.children.lowercase_result.method",
    ]

    assert tape.infer_hierarchical_bindings(paths) == {
        "service.Client_result": "service.Client",
        "service.Client_result.children.Helper_result": (
            "service.Client_result.children.Helper"
        ),
    }


def test_infer_hierarchical_bindings_deduplicates_repeated_prefixes():
    paths = [
        "pkg.Widget_result.first",
        "pkg.Widget_result.second",
        "pkg.Widget_result.deep.Child_result.call",
    ]

    assert tape.infer_hierarchical_bindings(paths) == {
        "pkg.Widget_result": "pkg.Widget",
        "pkg.Widget_result.deep.Child_result": "pkg.Widget_result.deep.Child",
    }


def test_infer_hierarchical_bindings_ignores_non_result_and_lowercase_segments():
    assert tape.infer_hierarchical_bindings(
        [
            "pkg.client_result.method",
            "pkg.Client.result",
            "pkg.Client_Result.method",
            "pkg.Client",
        ]
    ) == {}


def test_build_tape_returns_a_complete_replayable_payload_with_return_values_preferred():
    class Recorder:
        def __init__(self):
            self.timeline = [
                {
                    "seq": 0,
                    "t": 0.0,
                    "dir": "in",
                    "value": {"prompt": "hello"},
                },
                {
                    "seq": 1,
                    "t": 0.1,
                    "dir": "out",
                    "value": {"answer": "world"},
                },
            ]
            self.mocked_modules = {
                "api.Client": {
                    "methods": {
                        "create": {
                            "return_value": {"id": "client-1"},
                            "side_effect": None,
                        }
                    }
                },
                "api.Client_result": {
                    "methods": {"close": {"return_value": None}}
                },
            }
            self.value_index = {
                "value-1": {"kind": "dict", "value": {"prompt": "hello"}}
            }
            self.schemas = {
                "models.Response": {
                    "type": "object",
                    "properties": {"answer": {"type": "string"}},
                }
            }

    session_meta = {
        "sdk": "example",
        "captured_at": "2026-01-02T03:04:05Z",
        "duration_s": 0.5,
    }

    built = tape.build_tape(Recorder(), session_meta)

    assert built["session"] == session_meta
    assert built["timeline"] == [
        {
            "seq": 0,
            "t": 0.0,
            "dir": "in",
            "value": {"prompt": "hello"},
        },
        {
            "seq": 1,
            "t": 0.1,
            "dir": "out",
            "value": {"answer": "world"},
        },
    ]
    assert built["mocked_modules"]["api.Client"]["methods"]["create"] == {
        "return_value": {"id": "client-1"},
        "side_effect": None,
    }
    assert built["value_index"] == {
        "value-1": {"kind": "dict", "value": {"prompt": "hello"}}
    }
    assert built["metadata"] == {
        "capture_mode": "value_capture",
        "prefer_return_value": True,
    }
    assert built["nested_schemas"] == {
        "models.Response": {
            "type": "object",
            "properties": {"answer": {"type": "string"}},
        }
    }
    assert built["hierarchical_bindings"] == {
        "api.Client_result": "api.Client",
    }
    tape.validate_tape(built)


def test_build_tape_omits_empty_nested_schemas_but_keeps_other_sections():
    class Recorder:
        timeline = []
        mocked_modules = {}
        value_index = {}
        schemas = {}

    built = tape.build_tape(Recorder(), {"sdk": "example"})

    assert built == {
        "session": {"sdk": "example"},
        "timeline": [],
        "mocked_modules": {},
        "value_index": {},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
        "hierarchical_bindings": {},
    }


def test_build_tape_snapshots_the_schema_mapping_at_build_time():
    class Recorder:
        def __init__(self):
            self.timeline = []
            self.mocked_modules = {}
            self.value_index = {}
            self.schemas = {
                "models.Result": {
                    "type": "object",
                    "properties": {"ok": {"type": "boolean"}},
                }
            }

    recorder = Recorder()
    built = tape.build_tape(recorder, {"sdk": "example"})

    recorder.schemas["models.Error"] = {
        "type": "object",
        "properties": {"message": {"type": "string"}},
    }
    del recorder.schemas["models.Result"]

    assert built["nested_schemas"] == {
        "models.Result": {
            "type": "object",
            "properties": {"ok": {"type": "boolean"}},
        }
    }


def test_load_tape_returns_json_content_and_validates_it(tmp_path, monkeypatch):
    payload = _minimal_valid_tape()
    payload["value_index"] = {"id-1": {"value": 42}}
    path = tmp_path / "recording.json"
    path.write_text(json.dumps(payload), encoding="utf-8")

    validated = []

    def record_validation(loaded):
        validated.append(loaded)

    monkeypatch.setattr(tape, "validate_tape", record_validation)

    loaded = tape.load_tape(str(path))

    assert loaded == payload
    assert validated == [payload]


def test_load_tape_rejects_json_missing_required_tape_sections(tmp_path):
    path = tmp_path / "invalid.json"
    path.write_text(
        json.dumps(
            {
                "session": {"sdk": "example"},
                "timeline": [],
                "mocked_modules": {},
            }
        ),
        encoding="utf-8",
    )

    with pytest.raises(ValueError):
        tape.load_tape(str(path))

import pytest

from tapedeck.engine import serialize


class SnapshotChild:
    def __init__(self, label):
        self.label = label


class SnapshotParent:
    def __init__(self):
        self.name = "parent"
        self.count = 3
        self.child = SnapshotChild("nested")
        self._internal = "must not be recorded"


class EvolvingShape:
    pass


class ReprOnlyValue:
    __slots__ = ()

    def __repr__(self):
        return "ReprOnlyValue(payload=fallback-secret-value)"


class DeepReprValue:
    __slots__ = ()

    def __repr__(self):
        return "DeepReprValue(marker=deep-cutoff-marker, secret=deep-cutoff-secret)"


def test_secret_key_pattern_is_case_insensitive_and_does_not_match_unrelated_names():
    assert serialize.SECRET_KEY_RE.search("SERVICE_TOKEN")
    assert serialize.SECRET_KEY_RE.search("dbPassword")
    assert serialize.SECRET_KEY_RE.search("x-api_key-value")
    assert serialize.SECRET_KEY_RE.search("Authorization")
    assert serialize.SECRET_KEY_RE.search("refresh_token")
    assert serialize.SECRET_KEY_RE.search("credential_store")

    assert serialize.SECRET_KEY_RE.search("monkey") is None
    assert serialize.SECRET_KEY_RE.search("public_value") is None
    assert serialize.SECRET_KEY_RE.search("user_name") is None


def test_redactor_collects_only_secret_named_environment_values_and_extra_values():
    redactor = serialize.Redactor.from_environ(
        {
            "PUBLIC_GREETING": "hello-from-public-env",
            "SERVICE_TOKEN": "token-value-123",
            "DB_PASSWORD": "password-value-456",
            "AUTHORIZATION": "Bearer credential-789",
        },
        extra=(value for value in ("extra-secret-value",)),
    )

    original = (
        "public=hello-from-public-env; "
        "a=token-value-123; b=password-value-456; "
        "c=Bearer credential-789; d=extra-secret-value"
    )
    scrubbed = redactor.scrub(original)

    assert "hello-from-public-env" in scrubbed
    assert "token-value-123" not in scrubbed
    assert "password-value-456" not in scrubbed
    assert "Bearer credential-789" not in scrubbed
    assert "extra-secret-value" not in scrubbed
    assert redactor.scrub("a string with no known secret") == "a string with no known secret"


def test_redactor_scrubs_an_exactly_eight_character_secret_value():
    secret = "Ab3$xyZ!"
    redactor = serialize.Redactor.from_environ({"SERVICE_TOKEN": secret})

    scrubbed = redactor.scrub("authorization header contains " + secret + " here")

    assert scrubbed.startswith("authorization header contains ")
    assert scrubbed.endswith(" here")
    assert secret not in scrubbed


def test_redactor_ignores_empty_secret_values_and_handles_overlapping_secrets_safely():
    redactor = serialize.Redactor.from_environ(
        {
            "EMPTY_TOKEN": "",
            "SHORT_TOKEN": "abc",
            "LONG_PASSWORD": "abc123",
        }
    )

    assert redactor.scrub("ordinary text") == "ordinary text"

    scrubbed = redactor.scrub("value=abc123")
    assert "abc" not in scrubbed
    assert "abc123" not in scrubbed
    assert "123" not in scrubbed


def test_snapshot_preserves_json_primitives_and_converts_tuples_to_json_safe_lists():
    redactor = serialize.Redactor.from_environ({})
    schemas = {}

    value = {
        "none": None,
        "truth": True,
        "number": 12,
        "fraction": 2.5,
        "text": "safe text",
        "tuple": ("first", 2, False),
        "list": [None, "second"],
    }

    assert serialize.snapshot(value, redactor, schemas) == {
        "none": None,
        "truth": True,
        "number": 12,
        "fraction": 2.5,
        "text": "safe text",
        "tuple": ["first", 2, False],
        "list": [None, "second"],
    }
    assert schemas == {}


def test_snapshot_drops_secret_named_dict_keys_at_every_nesting_level_and_scrubs_values():
    secret = "very-sensitive-value"
    redactor = serialize.Redactor.from_environ({"SERVICE_TOKEN": secret})
    schemas = {}

    result = serialize.snapshot(
        {
            "visible": "prefix " + secret + " suffix",
            "api_key": "this whole entry must disappear",
            "nested": {
                "PASSWORD": "also disappears",
                "still_visible": [secret, {"refresh_token": "gone"}],
            },
        },
        redactor,
        schemas,
    )

    assert set(result) == {"visible", "nested"}
    assert result["visible"].startswith("prefix ")
    assert result["visible"].endswith(" suffix")
    assert secret not in result["visible"]

    assert set(result["nested"]) == {"still_visible"}
    assert isinstance(result["nested"]["still_visible"], list)
    assert secret not in result["nested"]["still_visible"][0]
    assert schemas == {}


def test_snapshot_serializes_public_object_attributes_and_records_nested_schemas():
    redactor = serialize.Redactor.from_environ({})
    schemas = {}

    result = serialize.snapshot(SnapshotParent(), redactor, schemas)

    assert result == {
        "__type__": "SnapshotParent",
        "name": "parent",
        "count": 3,
        "child": {
            "__type__": "SnapshotChild",
            "label": "nested",
        },
    }
    assert schemas == {
        "SnapshotParent": {
            "name": "str",
            "count": "int",
            "child": "SnapshotChild",
        },
        "SnapshotChild": {
            "label": "str",
        },
    }


def test_snapshot_scrubs_secret_strings_inside_object_attributes():
    secret = "object-only-secret"
    redactor = serialize.Redactor.from_environ({"CREDENTIAL": secret})
    schemas = {}

    item = SnapshotChild("contains " + secret + " here")
    result = serialize.snapshot(item, redactor, schemas)

    assert result["__type__"] == "SnapshotChild"
    assert result["label"].startswith("contains ")
    assert result["label"].endswith(" here")
    assert secret not in result["label"]
    assert schemas == {"SnapshotChild": {"label": "str"}}


def test_snapshot_uses_a_scrubbed_repr_for_values_without_json_or_object_attributes():
    secret = "fallback-secret-value"
    redactor = serialize.Redactor.from_environ({"SERVICE_TOKEN": secret})

    result = serialize.snapshot(ReprOnlyValue(), redactor, {})

    assert isinstance(result, str)
    assert result.startswith("ReprOnlyValue(payload=")
    assert result.endswith(")")
    assert secret not in result


def test_snapshot_limits_nested_collection_depth_without_losing_shallow_structure():
    value = "deep-leaf-that-must-not-be-recorded"
    for _ in range(200):
        value = [value]

    result = serialize.snapshot(value, serialize.Redactor.from_environ({}), {})

    current = result
    for _ in range(3):
        assert isinstance(current, list)
        assert len(current) == 1
        current = current[0]

    assert "deep-leaf-that-must-not-be-recorded" not in repr(result)


def test_snapshot_depth_limit_returns_a_scrubbed_diagnostic_representation():
    secret = "deep-cutoff-secret"
    value = DeepReprValue()
    for _ in range(100):
        value = [value]

    result = serialize.snapshot(
        value,
        serialize.Redactor.from_environ({"SERVICE_TOKEN": secret}),
        {},
    )

    current = result
    while isinstance(current, list):
        assert len(current) == 1
        current = current[0]

    assert isinstance(current, str)
    assert "deep-cutoff-marker" in current
    assert secret not in current


def test_snapshot_depth_increases_for_each_nested_collection_level():
    value = "terminal-value"
    for _ in range(80):
        value = [value]

    result = serialize.snapshot(value, serialize.Redactor.from_environ({}), {})

    list_levels = 0
    current = result
    while isinstance(current, list):
        assert len(current) == 1
        list_levels += 1
        current = current[0]

    assert list_levels < 40
    assert isinstance(current, str)


def test_snapshot_merges_schema_information_from_multiple_instances_of_same_type():
    first = EvolvingShape()
    first.name = "first"

    second = EvolvingShape()
    second.count = 2

    redactor = serialize.Redactor.from_environ({})
    schemas = {}

    assert serialize.snapshot(first, redactor, schemas) == {
        "__type__": "EvolvingShape",
        "name": "first",
    }
    assert serialize.snapshot(second, redactor, schemas) == {
        "__type__": "EvolvingShape",
        "count": 2,
    }
    assert schemas == {
        "EvolvingShape": {
            "name": "str",
            "count": "int",
        }
    }

import json
from types import SimpleNamespace

import pytest

from tapedeck.engine import tape


def valid_tape():
    return {
        "session": {
            "sdk": "pytest-sdk",
            "captured_at": "2026-10-02T12:00:00Z",
            "duration_s": 1.25,
        },
        "timeline": [
            {"seq": 0, "t": 0.0, "dir": "in", "method": "send"},
            {"seq": 1, "t": 0.2, "dir": "out", "value": {"ok": True}},
        ],
        "mocked_modules": {
            "example.Client": {
                "methods": {
                    "send": {"return_value": "ok"},
                }
            }
        },
        "value_index": {"value-1": {"answer": 42}},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }


def recorder_with(
    *,
    timeline=None,
    modules=None,
    values=None,
    schemas=None,
    capture_mode="unexpected-mode",
    prefer_return_value=False,
):
    timeline = [] if timeline is None else timeline
    modules = {} if modules is None else modules
    values = {} if values is None else values
    schemas = {} if schemas is None else schemas

    return SimpleNamespace(
        timeline=timeline,
        events=timeline,
        mocked_modules=modules,
        modules=modules,
        value_index=values,
        recorded_values=values,
        nested_schemas=schemas,
        schemas=schemas,
        capture_mode=capture_mode,
        prefer_return_value=prefer_return_value,
        metadata={
            "capture_mode": capture_mode,
            "prefer_return_value": prefer_return_value,
        },
        config=SimpleNamespace(
            capture_mode=capture_mode,
            prefer_return_value=prefer_return_value,
        ),
    )


def test_required_keys_matches_documented_contract():
    assert tape.REQUIRED_KEYS == (
        "session",
        "timeline",
        "mocked_modules",
        "metadata",
    )


def test_infer_hierarchical_bindings_finds_each_capitalized_result_prefix():
    paths = [
        "package.Client_result.request",
        "package.Client_result.children.Widget_result.execute",
        "package.Other_result",
        "package.lowercase_result.call",
        "package.Client_result.children.lowercase_result.call",
    ]

    assert tape.infer_hierarchical_bindings(paths) == {
        "package.Client_result": "package.Client",
        "package.Client_result.children.Widget_result": (
            "package.Client_result.children.Widget"
        ),
        "package.Other_result": "package.Other",
    }


def test_infer_hierarchical_bindings_accepts_mapping_keys_and_deduplicates_prefixes():
    containers = {
        "service.Factory_result.create": {},
        "service.Factory_result.close": {},
        "service.Factory_result.Child_result.run": {},
    }

    assert tape.infer_hierarchical_bindings(containers.keys()) == {
        "service.Factory_result": "service.Factory",
        "service.Factory_result.Child_result": "service.Factory_result.Child",
    }


