def test_build_tape_creates_a_complete_standalone_value_capture_artifact():
    session = {
        "sdk": "integration-sdk",
        "captured_at": "2026-10-02T12:34:56Z",
        "duration_s": 2.75,
    }
    timeline = [
        {"seq": 0, "t": 0.0, "dir": "in", "method": "open"},
        {"seq": 1, "t": 0.1, "dir": "out", "value": {"connected": True}},
    ]
    modules = {
        "demo.Client_result.request": {
            "methods": {
                "request": {"return_value": {"status": 200}},
            }
        },
        "demo.Client_result.Child_result.run": {
            "methods": {
                "run": {"return_value": "done"},
            }
        },
    }
    values = {
        "request-result": {"status": 200},
        "child-result": "done",
    }
    schemas = {
        "demo.Request": {"fields": {"path": "str", "headers": "dict"}},
        "demo.Response": {"fields": {"status": "int"}},
    }
    recorder = recorder_with(
        timeline=timeline,
        modules=modules,
        values=values,
        schemas=schemas,
        capture_mode="reference_capture",
        prefer_return_value=False,
    )

    built = tape.build_tape(recorder, session)

    assert built == {
        "session": session,
        "timeline": timeline,
        "mocked_modules": modules,
        "value_index": values,
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
        "nested_schemas": schemas,
        "hierarchical_bindings": {
            "demo.Client_result": "demo.Client",
            "demo.Client_result.Child_result": "demo.Client_result.Child",
        },
    }
    assert tape.validate_tape(built) is None

    assert built["nested_schemas"] is not schemas
    built["nested_schemas"]["demo.AddedAfterBuild"] = {"fields": {"id": "int"}}
    assert "demo.AddedAfterBuild" not in schemas


def test_build_tape_uses_recorder_schemas_not_stale_nested_schema_alias():
    current_schemas = {
        "demo.Current": {"fields": {"name": "str"}},
    }
    recorder = recorder_with(schemas=current_schemas)
    recorder.nested_schemas = {
        "demo.Stale": {"fields": {"obsolete": "bool"}},
    }

    built = tape.build_tape(
        recorder,
        {
            "sdk": "sdk",
            "captured_at": "2026-10-02T12:00:00Z",
            "duration_s": 0.0,
        },
    )

    assert built["nested_schemas"] == current_schemas
    assert "demo.Stale" not in built["nested_schemas"]

import pytest

import tapedeck.engine.serialize as serialize


def test_secret_key_pattern_matches_common_secret_names_case_insensitively():
    for key in (
        "TOKEN",
        "client_secret",
        "Password",
        "X-ApiKey",
        "api_key_id",
        "Authorization",
        "user_credential",
        "refresh_token",
    ):
        assert serialize.SECRET_KEY_RE.search(key)

    for key in ("username", "hostname", "session_id", "region", "email"):
        assert serialize.SECRET_KEY_RE.search(key) is None


def test_redactor_collects_exactly_eight_character_secret_values():
    secret = "12345678"
    redactor = serialize.Redactor.from_environ({"SERVICE_TOKEN": secret})

    assert redactor.scrub(f"before {secret} after") == "before [REDACTED] after"


def test_redactor_replaces_secret_occurrences_without_changing_visible_text():
    secret = "credential-value-123"
    redactor = serialize.Redactor.from_environ({}, extra=(secret,))

    assert (
        redactor.scrub(f"prefix {secret} middle {secret} suffix")
        == "prefix [REDACTED] middle [REDACTED] suffix"
    )


def test_redactor_collects_secret_named_environment_values_and_extra_values():
    long_secret = "long-tiny-secret"
    short_secret = "tiny"
    extra_secret = "extra-secret-value"

    redactor = serialize.Redactor.from_environ(
        {
            "SERVICE_TOKEN": short_secret,
            "API_KEY": long_secret,
            "EMPTY_SECRET": "",
            "REGION": "us-east-1",
        },
        extra=(value for value in (extra_secret,)),
    )

    scrubbed = redactor.scrub(
        f"start {long_secret} then {short_secret} then {extra_secret} in us-east-1 end"
    )

    assert long_secret not in scrubbed
    assert short_secret not in scrubbed
    assert extra_secret not in scrubbed
    assert "long-" not in scrubbed
    assert "-secret" not in scrubbed
    assert "us-east-1" in scrubbed


def test_redactor_does_not_treat_an_empty_secret_as_matching_every_position():
    redactor = serialize.Redactor.from_environ({"EMPTY_TOKEN": ""})

    assert redactor.scrub("ordinary visible text") == "ordinary visible text"


def test_snapshot_redacts_string_values_and_drops_secret_looking_dict_keys_recursively():
    secret = "credential-value-123"
    redactor = serialize.Redactor.from_environ({}, extra=(secret,))
    schemas = {}

    result = serialize.snapshot(
        {
            "username": "alice",
            "TOKEN": secret,
            "nested": {
                "apiKey": secret,
                "comment": f"prefix {secret} suffix",
                "count": 3,
            },
            "items": [secret, False, None],
            "notasecret": "must be removed because its name contains secret",
        },
        redactor,
        schemas,
    )

    assert set(result) == {"username", "nested", "items"}
    assert result["username"] == "alice"
    assert set(result["nested"]) == {"comment", "count"}
    assert result["nested"]["count"] == 3
    assert result["nested"]["comment"] == "prefix [REDACTED] suffix"
    assert result["items"] == ["[REDACTED]", False, None]
    assert schemas == {}


def test_snapshot_of_objects_includes_only_public_attributes_and_records_schema():
    class Address:
        def __init__(self):
            self.city = "Paris"
            self._internal_code = "not public"

    class Customer:
        def __init__(self):
            self.name = "Ada"
            self.age = 37
            self.address = Address()
            self._cache = {"ignored": True}

    redactor = serialize.Redactor.from_environ({})
    schemas = {}

    result = serialize.snapshot(Customer(), redactor, schemas)

    assert result == {
        "__type__": "Customer",
        "name": "Ada",
        "age": 37,
        "address": {
            "__type__": "Address",
            "city": "Paris",
        },
    }
    assert schemas == {
        "Customer": {
            "name": "str",
            "age": "int",
            "address": "Address",
        },
        "Address": {
            "city": "str",
        },
    }


def test_snapshot_preserves_json_scalar_types_and_converts_tuples_to_json_safe_lists():
    redactor = serialize.Redactor.from_environ({})
    schemas = {}

    result = serialize.snapshot(
        {
            "none": None,
            "truth": True,
            "number": 4.5,
            "tuple": ("one", 2, False),
        },
        redactor,
        schemas,
    )

    assert result == {
        "none": None,
        "truth": True,
        "number": 4.5,
        "tuple": ["one", 2, False],
    }
    assert schemas == {}


def test_snapshot_uses_a_redacted_repr_for_values_without_serializable_attributes():
    secret = "opaque-secret-value"

    class Opaque:
        __slots__ = ()

        def __repr__(self):
            return f"Opaque(token={secret})"

    result = serialize.snapshot(
        Opaque(),
        serialize.Redactor.from_environ({}, extra=(secret,)),
        {},
    )

    assert result == "Opaque(token=[REDACTED])"


def test_snapshot_stops_descending_after_maximum_depth():
    leaf = {"marker": "visible"}
    value = leaf

    for _ in range(serialize._MAX_DEPTH + 1):
        value = [value]

    expected = repr(leaf)
    for _ in range(serialize._MAX_DEPTH + 1):
        expected = [expected]

    assert serialize.snapshot(
        value,
        serialize.Redactor.from_environ({}),
        {},
    ) == expected


def test_snapshot_at_depth_limit_uses_redacted_repr_instead_of_serializing_object_attributes():
    secret = "depth-limit-secret"

    class CredentialCarrier:
        def __init__(self):
            self.visible = "ordinary public value"

        def __repr__(self):
            return f"CredentialCarrier(token={secret})"

    result = serialize.snapshot(
        [CredentialCarrier()],
        serialize.Redactor.from_environ({}, extra=(secret,)),
        {},
        depth=serialize._MAX_DEPTH,
    )

    assert result == ["CredentialCarrier(token=[REDACTED])"]


def test_snapshot_increments_depth_when_descending_into_list_items():
    result = serialize.snapshot(
        [{"marker": "visible"}],
        serialize.Redactor.from_environ({}),
        {},
        depth=serialize._MAX_DEPTH,
    )

    assert result == [repr({"marker": "visible"})]

import json

import pytest

from tapedeck.engine import tape


def valid_tape():
    return {
        "session": {
            "sdk": "tapedeck-python",
            "captured_at": "2026-01-02T03:04:05Z",
            "duration_s": 1.25,
        },
        "timeline": [
            {"seq": 0, "t": 0.0, "dir": "in", "value": {"name": "Ada"}},
            {"seq": 1, "t": 0.1, "dir": "out", "value": {"ok": True}},
        ],
        "mocked_modules": {
            "example.Client": {
                "methods": {
                    "send": {"return_value": {"ok": True}},
                }
            }
        },
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }


def test_required_keys_matches_documented_public_contract():
    assert tape.REQUIRED_KEYS == (
        "session",
        "timeline",
        "mocked_modules",
        "metadata",
    )


def test_validate_tape_accepts_minimal_valid_tape_without_optional_sections():
    subject = valid_tape()

    assert tape.validate_tape(subject) is None
    assert "value_index" not in subject
    assert "nested_schemas" not in subject
    assert "hierarchical_bindings" not in subject


@pytest.mark.parametrize("missing_key", tape.REQUIRED_KEYS)
def test_validate_tape_rejects_each_required_top_level_key(missing_key):
    subject = valid_tape()
    del subject[missing_key]

    with pytest.raises(ValueError):
        tape.validate_tape(subject)


@pytest.mark.parametrize(
    "bad_timeline",
    [
        {},
        "not a list",
        [{"seq": 0, "t": 0.0, "dir": "sideways"}],
        [{"seq": 0, "t": 0.0}],
    ],
)
def test_validate_tape_rejects_invalid_timeline_shapes_and_directions(bad_timeline):
    subject = valid_tape()
    subject["timeline"] = bad_timeline

    with pytest.raises(ValueError):
        tape.validate_tape(subject)


@pytest.mark.parametrize(
    "key,bad_value",
    [
        ("session", []),
        ("mocked_modules", []),
        ("metadata", []),
    ],
)
def test_validate_tape_rejects_wrong_types_for_structural_sections(key, bad_value):
    subject = valid_tape()
    subject[key] = bad_value

    with pytest.raises(ValueError):
        tape.validate_tape(subject)


def test_infer_hierarchical_bindings_finds_class_result_prefixes_at_any_depth():
    paths = [
        "service.Client",
        "service.Client_result.request",
        "service.Client_result.request_result",
        "pkg.Outer.Inner_result.call",
        "pkg.Outer.Inner_result.call.more",
        "pkg.lowercase_result.method",
        "pkg.Widget_result",
        "pkg.Widget_result_more.method",
    ]

    assert tape.infer_hierarchical_bindings(paths) == {
        "service.Client_result": "service.Client",
        "pkg.Outer.Inner_result": "pkg.Outer.Inner",
        "pkg.Widget_result": "pkg.Widget",
    }


def test_infer_hierarchical_bindings_deduplicates_repeated_prefixes():
    paths = [
        "api.Session_result.get",
        "api.Session_result.post",
        "api.Session_result.headers.items",
    ]

    assert tape.infer_hierarchical_bindings(paths) == {
        "api.Session_result": "api.Session",
    }


class RecorderLike:
    def __init__(self):
        self.timeline = [
            {"seq": 0, "t": 0.0, "dir": "in", "value": "request"},
            {"seq": 1, "t": 0.2, "dir": "out", "value": "response"},
        ]
        self.mocked_modules = {
            "demo.Client": {
                "methods": {
                    "fetch": {"return_value": "response"},
                }
            }
        }
        self.value_index = {"value-1": {"kind": "str", "value": "response"}}
        self.capture_mode = "reference_capture"
        self.prefer_return_value = False
        self.schemas = {
            "demo.Client_result": {
                "type": "object",
                "properties": {"status": {"type": "string"}},
            },
            "demo.Request": {
                "type": "object",
                "properties": {"query": {"type": "string"}},
            },
        }
        self.container_paths = list(self.mocked_modules)


def session_meta():
    return {
        "sdk": "tapedeck-python",
        "captured_at": "2026-01-02T03:04:05Z",
        "duration_s": 0.2,
    }


def test_build_tape_produces_a_replayable_tape_with_canonical_replay_metadata():
    recorder = RecorderLike()

    built = tape.build_tape(recorder, session_meta())

    assert built["session"] == session_meta()
    assert built["timeline"] == recorder.timeline
    assert built["mocked_modules"] == recorder.mocked_modules
    assert built["value_index"] == recorder.value_index

    # A saved tape is replayed using values and return values, regardless of
    # transient recorder settings used while it was captured.
    assert built["metadata"] == {
        "capture_mode": "value_capture",
        "prefer_return_value": True,
    }
    assert tape.validate_tape(built) is None


def test_build_tape_preserves_all_discovered_nested_schemas_for_replay():
    recorder = RecorderLike()

    built = tape.build_tape(recorder, session_meta())

    assert built["nested_schemas"] == {
        "demo.Client_result": {
            "type": "object",
            "properties": {"status": {"type": "string"}},
        },
        "demo.Request": {
            "type": "object",
            "properties": {"query": {"type": "string"}},
        },
    }

    # The tape owns its top-level schema registry after it has been built.
    recorder.schemas["later.Added"] = {"type": "null"}
    assert "later.Added" not in built["nested_schemas"]


def test_build_tape_returns_the_completed_tape_object_not_just_side_effects():
    recorder = RecorderLike()

    built = tape.build_tape(recorder, session_meta())

    assert built["timeline"] == [
        {"seq": 0, "t": 0.0, "dir": "in", "value": "request"},
        {"seq": 1, "t": 0.2, "dir": "out", "value": "response"},
    ]
    assert built["metadata"]["prefer_return_value"] is True
    assert built["nested_schemas"]["demo.Client_result"]["type"] == "object"
    assert tape.validate_tape(built) is None


def test_load_tape_reads_json_and_validates_it(tmp_path):
    subject = valid_tape()
    path = tmp_path / "recording.json"
    path.write_text(json.dumps(subject), encoding="utf-8")

    assert tape.load_tape(str(path)) == subject


def test_load_tape_rejects_json_that_is_not_a_valid_tape(tmp_path):
    path = tmp_path / "incomplete.json"
    path.write_text(json.dumps({"session": {}}), encoding="utf-8")

    with pytest.raises(ValueError):
        tape.load_tape(str(path))


def test_load_tape_rejects_malformed_json(tmp_path):
    path = tmp_path / "broken.json"
    path.write_text('{"session": ', encoding="utf-8")

    with pytest.raises(ValueError):
        tape.load_tape(str(path))

import pytest

import tapedeck.engine.serialize as serialize


def test_secret_key_regex_matches_documented_secret_names_case_insensitively():
    for key in (
        "TOKEN",
        "access_token",
        "clientSecret",
        "PASSWORD",
        "api_key",
        "apikey",
        "Authorization",
        "user_credential",
        "refresh_token",
    ):
        assert serialize.SECRET_KEY_RE.search(key)

    for key in ("username", "email", "host", "database", "public_value"):
        assert serialize.SECRET_KEY_RE.search(key) is None


def test_redactor_collects_only_secret_environment_values_and_extra_values():
    redactor = serialize.Redactor.from_environ(
        {
            "SERVICE_TOKEN": "env-token-123",
            "PASSWORD": "env-password-456",
            "PUBLIC_LABEL": "ordinary-environment-value",
            "EMPTY_SECRET": "",
        },
        extra=(value for value in ("manual-secret-789", "")),
    )

    text = (
        "before env-token-123 middle env-password-456 "
        "and manual-secret-789 after"
    )
    scrubbed = redactor.scrub(text)

    assert "env-token-123" not in scrubbed
    assert "env-password-456" not in scrubbed
    assert "manual-secret-789" not in scrubbed
    assert scrubbed.startswith("before ")
    assert scrubbed.endswith(" after")

    assert redactor.scrub("ordinary-environment-value") == "ordinary-environment-value"
    assert redactor.scrub("a normal value") == "a normal value"


def test_redactor_scrubs_secret_values_at_the_minimum_supported_length():
    secret = "edgepass"
    assert len(secret) == 8

    redactor = serialize.Redactor.from_environ({"SESSION_TOKEN": secret})
    scrubbed = redactor.scrub(f"prefix {secret} suffix")

    assert secret not in scrubbed
    assert scrubbed.startswith("prefix ")
    assert scrubbed.endswith(" suffix")

    schemas = {}
    snapshot = serialize.snapshot(
        {"message": f"prefix {secret} suffix"},
        redactor,
        schemas,
    )

    assert secret not in snapshot["message"]
    assert snapshot["message"].startswith("prefix ")
    assert snapshot["message"].endswith(" suffix")
    assert schemas == {}


def test_snapshot_redacts_secret_keyed_values_and_secret_substrings_recursively():
    redactor = serialize.Redactor.from_environ(
        {"API_TOKEN": "top-secret-value"},
        extra=("second-secret",),
    )
    schemas = {}

    result = serialize.snapshot(
        {
            "visible": "prefix top-secret-value suffix",
            "access_token": "this entire field must disappear",
            "nested": {
                "password_hint": "also disappears because its key looks secret",
                "safe": "contains second-secret in the middle",
            },
            "items": [
                {"authorization": "drop this"},
                "top-secret-value",
                7,
            ],
        },
        redactor,
        schemas,
    )

    assert set(result) == {"visible", "nested", "items"}
    assert set(result["nested"]) == {"safe"}
    assert set(result["items"][0]) == set()
    assert result["items"][2] == 7

    assert "top-secret-value" not in result["visible"]
    assert result["visible"].startswith("prefix ")
    assert result["visible"].endswith(" suffix")
    assert "second-secret" not in result["nested"]["safe"]
    assert "top-secret-value" not in result["items"][1]
    assert schemas == {}


def test_snapshot_preserves_json_primitives_and_converts_tuple_to_json_array():
    redactor = serialize.Redactor.from_environ({})
