    result = serialize.snapshot(
        {
            "none": None,
            "boolean": True,
            "integer": 3,
            "float": 1.25,
            "text": "hello",
            "tuple": ("first", 2, False),
            "list": ["second", 4],
        },
        redactor,
        schemas,
    )

    assert result == {
        "none": None,
        "boolean": True,
        "integer": 3,
        "float": 1.25,
        "text": "hello",
        "tuple": ["first", 2, False],
        "list": ["second", 4],
    }
    assert schemas == {}


def test_snapshot_uses_scrubbed_repr_for_opaque_values_without_public_attributes():
    class OpaqueValue:
        __slots__ = ()

        def __repr__(self):
            return "OpaqueValue(connection='opaque-secret-123')"

    value = OpaqueValue()
    redactor = serialize.Redactor.from_environ(
        {"CONNECTION_TOKEN": "opaque-secret-123"}
    )
    schemas = {}

    result = serialize.snapshot(value, redactor, schemas)

    assert result == redactor.scrub(repr(value))
    assert result.startswith("OpaqueValue(connection='")
    assert result.endswith("')")
    assert "opaque-secret-123" not in result
    assert schemas == {}


def test_snapshot_objects_include_public_attributes_and_build_nested_schemas():
    class Address:
        def __init__(self):
            self.city = "London"
            self.zip_code = 12345
            self._internal_note = "must not be serialized"

    class User:
        def __init__(self):
            self.name = "Ada"
            self.age = 42
            self.active = True
            self.address = Address()
            self.tags = ("admin", "tester")
            self._cache = "private"

    redactor = serialize.Redactor.from_environ({})
    schemas = {}

    result = serialize.snapshot(User(), redactor, schemas)

    assert result == {
        "__type__": "User",
        "name": "Ada",
        "age": 42,
        "active": True,
        "address": {
            "__type__": "Address",
            "city": "London",
            "zip_code": 12345,
        },
        "tags": ["admin", "tester"],
    }
    assert schemas == {
        "User": {
            "name": "str",
            "age": "int",
            "active": "bool",
            "address": "Address",
            "tags": "tuple",
        },
        "Address": {
            "city": "str",
            "zip_code": "int",
        },
    }


def test_snapshot_omits_secret_named_object_attributes_from_snapshot_and_schema():
    class Credentials:
        def __init__(self):
            self.username = "alice"
            self.api_key = "should-never-appear"
            self.refreshToken = "should-also-never-appear"
            self.note = "safe note"

    redactor = serialize.Redactor.from_environ({})
    schemas = {}

    result = serialize.snapshot(Credentials(), redactor, schemas)

    assert result == {
        "__type__": "Credentials",
        "username": "alice",
        "note": "safe note",
    }
    assert schemas == {
        "Credentials": {
            "username": "str",
            "note": "str",
        }
    }


def test_snapshot_stops_descending_into_recursive_collections_at_depth_limit():
    recursive_list = []
    recursive_list.append(recursive_list)

    schemas = {}
    result = serialize.snapshot(
        recursive_list,
        serialize.Redactor.from_environ({}),
        schemas,
    )

    current = result
    for _ in range(100):
        if not isinstance(current, list):
            break
        assert len(current) == 1
        current = current[0]
    else:
        pytest.fail("recursive collection was not truncated at the depth limit")

    assert isinstance(current, str)
    assert schemas == {}

import json

import pytest

from tapedeck.engine import tape


def make_valid_tape():
    return {
        "session": {
            "sdk": {"name": "pytest-sdk", "version": "1.0"},
            "captured_at": "2026-01-01T00:00:00Z",
            "duration_s": 0.0,
        },
        "timeline": [],
        "mocked_modules": {},
        "value_index": {},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }


def test_required_keys_match_documented_public_contract():
    assert tape.REQUIRED_KEYS == (
        "session",
        "timeline",
        "mocked_modules",
        "metadata",
    )


def test_build_tape_creates_complete_value_capture_document_and_owns_schema_mapping():
    class RecorderStub:
        timeline = [
            {
                "seq": 0,
                "t": 0.0,
                "dir": "in",
                "container": "package.Client",
                "method": "request",
            }
        ]
        mocked_modules = {
            "package.Client": {
                "methods": {
                    "request": {
                        "capture_args": True,
                        "capture_return": True,
                    }
                }
            }
        }
        value_index = {"value-1": {"kind": "str", "value": "hello"}}
        schemas = {
            "package.Client_result": {
                "type": "object",
                "properties": {"status": {"type": "string"}},
            }
        }
        container_paths = [
            "package.Client",
            "package.Client_result.request",
        ]

    recorder = RecorderStub()
    session_meta = {
        "sdk": {"name": "example-sdk", "version": "2.0"},
        "captured_at": "2026-01-01T00:00:00Z",
        "duration_s": 1.25,
    }

    built = tape.build_tape(recorder, session_meta)

    assert built == {
        "session": session_meta,
        "timeline": recorder.timeline,
        "mocked_modules": recorder.mocked_modules,
        "value_index": recorder.value_index,
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
        "nested_schemas": {
            "package.Client_result": {
                "type": "object",
                "properties": {"status": {"type": "string"}},
            }
        },
        "hierarchical_bindings": {
            "package.Client_result": "package.Client",
        },
    }

    recorder.schemas["package.Other_result"] = {"type": "string"}

    assert built["nested_schemas"] == {
        "package.Client_result": {
            "type": "object",
            "properties": {"status": {"type": "string"}},
        }
    }


def test_build_tape_uses_return_values_by_default_even_without_optional_data():
    class RecorderStub:
        timeline = []
        mocked_modules = {}
        value_index = {}
        schemas = {}
        container_paths = []

    session_meta = {
        "sdk": {"name": "minimal-sdk", "version": "1.0"},
        "captured_at": "2026-01-01T00:00:00Z",
        "duration_s": 0.0,
    }

    built = tape.build_tape(RecorderStub(), session_meta)

    assert built["metadata"] == {
        "capture_mode": "value_capture",
        "prefer_return_value": True,
    }
    assert built["session"] == session_meta
    assert built["timeline"] == []
    assert built["mocked_modules"] == {}
    assert built["value_index"] == {}


def test_validate_tape_accepts_a_complete_documented_tape():
    document = make_valid_tape()

    assert tape.validate_tape(document) is None


@pytest.mark.parametrize("missing_key", tape.REQUIRED_KEYS)
def test_validate_tape_rejects_each_missing_required_top_level_key(missing_key):
    document = make_valid_tape()
    del document[missing_key]

    with pytest.raises(ValueError):
        tape.validate_tape(document)


def test_validate_tape_does_not_treat_value_index_as_a_required_key():
