        value = [value]

    redactor = serialize.Redactor.from_environ({"ACCESS_TOKEN": secret})
    result = serialize.snapshot(value, redactor, {})

    observed_levels = 0
    terminal = result
    while isinstance(terminal, list):
        assert len(terminal) == 1
        observed_levels += 1
        terminal = terminal[0]

    assert 0 < observed_levels < nested_levels
    assert isinstance(terminal, str)
    assert secret not in terminal
    assert secret not in json.dumps(result)


