import json

import pytest

from tapedeck.engine import tape


def _minimal_tape():
    return {
        "session": {
            "sdk": "pytest-sdk",
            "captured_at": "2026-01-01T00:00:00Z",
            "duration_s": 0.25,
        },
        "timeline": [],
        "mocked_modules": {},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }


class FakeRecorder:
    def __init__(self):
        self.timeline = [
            {
                "seq": 0,
                "t": 0.0,
                "dir": "in",
                "container": "example.Client",
                "method": "fetch",
                "args": ["abc"],
            },
            {
                "seq": 1,
                "t": 0.1,
                "dir": "out",
                "value": {"id": 7},
            },
        ]
        self.mocked_modules = {
            "example.Client": {
                "methods": {
                    "fetch": {
                        "signature": "(key)",
                    }
                }
            }
        }
        self.value_index = {"value-1": {"id": 7}}

        # The tape format has fixed replay semantics and must not inherit
        # incidental recorder settings.
        self.capture_mode = "reference_capture"
        self.prefer_return_value = False

        self.schemas = {
            "example.Client.fetch": {
                "result": {"id": "int"},
            }
        }
        self.nested_schemas = {
            "incorrect.source": {
                "result": {"should_not": "be_used"},
            }
        }
        self.container_paths = {
            "example.Client_result.fetch",
            "example.Client_result.Worker_result.run",
        }


def _session_meta():
    return {
        "sdk": "tapedeck-python",
        "captured_at": "2026-01-01T12:00:00Z",
        "duration_s": 1.5,
    }


def test_build_tape_produces_a_valid_replay_document_with_fixed_capture_policy():
    recorder = FakeRecorder()

    built = tape.build_tape(recorder, _session_meta())

    # This validates that build_tape returned a usable tape, rather than merely
    # a partial intermediate dictionary.
    assert tape.validate_tape(built) is None
    assert built["session"] == _session_meta()
    assert built["timeline"] == recorder.timeline
    assert built["mocked_modules"] == recorder.mocked_modules
    assert built["value_index"] == recorder.value_index

    # These are tape-format semantics, not recorder configuration.
    assert built["metadata"] == {
        "capture_mode": "value_capture",
        "prefer_return_value": True,
    }


def test_build_tape_records_recorder_schemas_and_derived_hierarchical_bindings():
    recorder = FakeRecorder()

    built = tape.build_tape(recorder, _session_meta())

    assert built["nested_schemas"] == {
        "example.Client.fetch": {
            "result": {"id": "int"},
        }
    }
    assert built["hierarchical_bindings"] == {
        "example.Client_result": "example.Client",
        "example.Client_result.Worker_result": "example.Client_result.Worker",
    }


def test_build_tape_schema_mapping_is_independent_of_later_recorder_additions():
    recorder = FakeRecorder()

    built = tape.build_tape(recorder, _session_meta())
    recorder.schemas["example.Other.method"] = {"result": "str"}

    assert built["nested_schemas"] == {
        "example.Client.fetch": {
            "result": {"id": "int"},
        }
    }


def test_built_tape_can_be_serialized_and_loaded_without_losing_capture_details(tmp_path):
    recorder = FakeRecorder()
    built = tape.build_tape(recorder, _session_meta())

    path = tmp_path / "built-recording.json"
    path.write_text(json.dumps(built), encoding="utf-8")

    loaded = tape.load_tape(str(path))

    assert loaded["metadata"]["prefer_return_value"] is True
    assert loaded["nested_schemas"] == recorder.schemas
    assert loaded["hierarchical_bindings"] == {
        "example.Client_result": "example.Client",
        "example.Client_result.Worker_result": "example.Client_result.Worker",
    }
    assert loaded["timeline"] == recorder.timeline


def test_infer_hierarchical_bindings_finds_each_capitalized_result_prefix():
    paths = [
        "pkg.Client_result.request",
        "pkg.Client_result.Worker_result.execute",
        "pkg.Other_result",
