        "pkg.Client_result_extra.request",
        "pkg.normal.path",
    ]

    result = tape.infer_hierarchical_bindings(paths)

    assert result == {
        "pkg.Client_result": "pkg.Client",
        "pkg.Client_result.Worker_result": "pkg.Client_result.Worker",
        "pkg.Other_result": "pkg.Other",
